{"source": "def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {OR IGNORE, OR REPLACE, ON CONFLICT DO UPDATE value}
    # trigger: none or AFTER INSERT log insert
    # channel: changes(), total_changes(main), total_changes(main)+total_changes(other)
    # We must determine which combination is consistent with all receipts,
    # then predict the goal for the query sequence.

    def simulate(put_mode, has_trigger, channel_mode, actions):
        # returns (channel, committed_count, committed_sum)
        # state: dict key->value for committed main db
        # pending transaction state per connection
        committed = {}
        # transaction buffers: None means no open txn
        txn = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() on main
        last_changes_main = 0
        # trigger log count (unread, but affects total_changes)
        # We'll track total_changes including trigger inserts.

        def apply_put(conn, key, value):
            nonlocal last_changes_main
            # determine current view for this connection
            if txn[conn] is not None:
                view = txn[conn]
            else:
                view = committed
            # simulate insert
            direct = 0
            trig = 0
            if key in view:
                if put_mode == "ignore":
                    direct = 0
                elif put_mode == "replace":
                    view[key] = value
                    direct = 1
                else:  # update
                    view[key] = value
                    direct = 1
            else:
                view[key] = value
                direct = 1
            if direct == 1 and has_trigger:
                trig = 1
            if conn == "main":
                last_changes_main = direct
            tc[conn] += direct + trig

        def apply_update(conn, key, value):
            nonlocal last_changes_main
            if txn[conn] is not None:
                view = txn[conn]
            else:
                view = committed
            direct = 0
            if key in view:
                view[key] = value
                direct = 1
            if conn == "main":
                last_changes_main = direct
            tc[conn] += direct

        def apply_delete(conn, key):
            nonlocal last_changes_main
            if txn[conn] is not None:
                view = txn[conn]
            else:
                view = committed
            direct = 0
            if key in view:
                del view[key]
                direct = 1
            if conn == "main":
                last_changes_main = direct
            tc[conn] += direct

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                apply_put(conn, act["key"], act["value"])
            elif op == "update":
                apply_update(conn, act["key"], act["value"])
            elif op == "delete":
                apply_delete(conn, act["key"])
            elif op == "begin":
                txn[conn] = dict(committed)
            elif op == "commit":
                if txn[conn] is not None:
                    committed.clear()
                    committed.update(txn[conn])
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None

        if channel_mode == "changes":
            ch = last_changes_main
        elif channel_mode == "total_main":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "update"]
    trigger_opts = [False, True]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
    for pm in put_modes:
        for ht in trigger_opts:
            for cm in channel_modes:
                ok = True
                for rec in hist:
                    ch, cc, cs = simulate(pm, ht, cm, rec["actions"])
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, ht, cm))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for pm, ht, cm in candidates:
        ch, cc, cs = simulate(pm, ht, cm, actions)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cc)
        elif goal == "committed_sum":
            results.add(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Predicts channel, committed_count, or committed_sum for a fresh action sequence by enumerating the disclosed 18-member family (put mode x trigger x channel) and keeping only combinations consistent with all calibration receipts.", "lesson": "The receipts constrain put conflict handling, trigger presence, and counter channel jointly; simulating each candidate and intersecting predictions yields a supported value only when all surviving candidates agree."}
